/**
 * Molkobain markdown viewer: Helpers shared by the console and the portal to render markdown attributes
 *
 * Note: Requires showdown.js and DOMPurify
 * Note: Declared with "var" on purpose, as this file can be loaded several times in the same page (eg. AJAX modals)
 */
var MolkobainMarkdownViewer = {
	/** @var {string} Format of a plain text attribute, see AttributeText::GetFormat() */
	ENUM_FORMAT_TEXT: 'text',
	/** @var {string} Format of an HTML attribute (edited with CKEditor), see AttributeText::GetFormat() */
	ENUM_FORMAT_HTML: 'html',

	/** @var {Array} Tags laid out as blocks, meaning they start on a new line */
	BLOCK_TAGS: ['address', 'article', 'aside', 'blockquote', 'caption', 'center', 'dd', 'details', 'dialog', 'div', 'dl', 'dt', 'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'legend', 'li', 'main', 'nav', 'ol', 'p', 'pre', 'section', 'summary', 'table', 'tbody', 'td', 'tfoot', 'th', 'thead', 'tr', 'ul'],
	/** @var {Array} Tags whose content is not text typed by the user */
	IGNORED_TAGS: ['audio', 'button', 'canvas', 'embed', 'head', 'iframe', 'input', 'math', 'noscript', 'object', 'script', 'select', 'style', 'svg', 'template', 'textarea', 'title', 'video'],

	/** @var {Object|null} DOMPurify instance, see GetSanitizer() */
	oSanitizer: null,
	/** @var {Object|null} Rules of the iTop HTML sanitizer applied by the current sanitization, see Sanitize() */
	oSanitizerRules: null,
	/** @var {Object} PCRE patterns of the iTop HTML sanitizer => JS regular expression (null if it could not be converted), see ConvertPattern() */
	oPatternRegExps: {},

	/**
	 * @param {Object} oValueElem jQuery object of the element containing the value, as displayed by iTop in read-only mode
	 * @param {string} sFormat Format of the attribute, see ENUM_FORMAT_XXX
	 *
	 * @return {string} The markdown typed by the user
	 */
	GetMarkdownFromDisplayedValue: function (oValueElem, sFormat) {
		if (oValueElem.length === 0) {
			return '';
		}

		if (sFormat !== this.ENUM_FORMAT_HTML) {
			return this.GetTextFromDisplayedText(oValueElem[0]);
		}

		return this.GetMarkdownFromHtml(oValueElem[0]);
	},

	/**
	 * Plain text is displayed escaped, with a <br> for each line ending. Line endings are retrieved from the <br> only, as the line ending characters around them vary:
	 * The console puts them after the <br>, whereas the portal puts the "\n" after the <br> and the "\r" (if any) before it, which the browser turns into another "\n".
	 *
	 * @param {Node} oNode Node containing a plain text attribute as displayed by iTop
	 *
	 * @return {string} The original text
	 */
	GetTextFromDisplayedText: function (oNode) {
		let sText = '';
		oNode.childNodes.forEach((oChildNode) => {
			if (oChildNode.nodeType === Node.TEXT_NODE) {
				sText += oChildNode.nodeValue.replace(/[\r\n]/g, '');
			} else if (oChildNode.nodeType === Node.ELEMENT_NODE) {
				// Note: Other elements are hyperlinks made by iTop from URLs and wiki links, only their text is kept
				sText += (oChildNode.tagName.toLowerCase() === 'br') ? '\n' : this.GetTextFromDisplayedText(oChildNode);
			}
		});

		return sText;
	},

	/**
	 * @param {Object} oInputElem jQuery object of the textarea used to edit the value
	 * @param {string} sFormat Format of the attribute, see ENUM_FORMAT_XXX
	 *
	 * @return {string} The markdown being typed by the user
	 */
	GetMarkdownFromEditedValue: function (oInputElem, sFormat) {
		if (sFormat !== this.ENUM_FORMAT_HTML) {
			return oInputElem.val();
		}

		// Parsed in a separate document, so nothing is loaded or executed
		const oDocument = new DOMParser().parseFromString(this.GetRichTextEditorValue(oInputElem), 'text/html');

		return this.GetMarkdownFromHtml(oDocument.body);
	},

	/**
	 * @param {Object} oInputElem jQuery object of the textarea on which CKEditor is instantiated
	 *
	 * @return {string} Current HTML of the editor, as CKEditor only updates the textarea a few seconds after the last change
	 */
	GetRichTextEditorValue: function (oInputElem) {
		const sInputId = oInputElem.attr('id');
		if ((sInputId !== undefined) && (typeof CombodoCKEditorHandler !== 'undefined')) {
			const oEditor = CombodoCKEditorHandler.GetInstanceSynchronous('#' + sInputId);
			if (oEditor) {
				return oEditor.getData();
			}
		}

		return oInputElem.val();
	},

	/**
	 * Retrieve the markdown typed by the user from the HTML generated by CKEditor:
	 *  - Lines typed with "Shift + Enter" are separated by a <br>, lines typed with "Enter" and blank lines of a pasted text are separate <p>
	 *  - Leading and consecutive spaces are non-breaking spaces
	 *  - Elements inserted through the toolbar (images, links, lists, tables, ...) are converted to their markdown equivalent
	 *
	 * @param {Node} oRootNode Node containing the HTML
	 *
	 * @return {string}
	 */
	GetMarkdownFromHtml: function (oRootNode) {
		// No markup at all (eg. value set through the REST API or an import), line breaks are already in the text
		if (oRootNode.children.length === 0) {
			return this.ReplaceNonBreakingSpaces(oRootNode.textContent);
		}

		return this.JoinBlocks(this.ConvertChildrenToBlocks(oRootNode)).replace(/^\n+|\s+$/g, '');
	},

	/**
	 * Convert sMarkdown to HTML
	 *
	 * @param {string} sMarkdown
	 * @param {Object} oConverterOptions Options of the showdown converter
	 * @param {Object} oSanitizerRules Rules of the HTML sanitizer configured in iTop, see ConfigHelper::GetHTMLSanitizerRules()
	 *
	 * @return {DocumentFragment} Sanitized HTML, ready to be inserted in the page
	 */
	MakeHtml: function (sMarkdown, oConverterOptions, oSanitizerRules) {
		const sHtml = new showdown.Converter(oConverterOptions).makeHtml(sMarkdown);

		// Important: Markdown can contain raw HTML and showdown doesn't check URLs (eg. "javascript:"), so its output must be sanitized
		return this.Sanitize(sHtml, oSanitizerRules);
	},

	/**
	 * Enable zoom on the images of oElem
	 *
	 * @param {Object} oElem jQuery object
	 * @param {number} iImageMaxWidth See "inline_image_max_display_width" config. parameter
	 */
	EnableImageZoom: function (oElem, iImageMaxWidth) {
		if (iImageMaxWidth === 0) {
			return;
		}

		oElem.find('img').each(function () {
			if ($(this).width() > iImageMaxWidth) {
				$(this).css({'max-width': iImageMaxWidth + 'px', width: '', height: '', 'max-height': ''});
			}
			$(this).addClass('inline-image').attr('href', $(this).attr('src'));
		}).magnificPopup({type: 'image', closeOnContentClick: true});
	},

	/**
	 * Sanitize sHtml with DOMPurify following the rules of the HTML sanitizer configured in iTop (see DOMSanitizer::CleanNode()), on top of DOMPurify own protections (scripts, event handlers, "javascript:" URLs, ...).
	 * Note: Unlike iTop, the content of a forbidden element is kept (except for dangerous ones such as "script"), so no text typed by the user is lost (eg. "h5" headings are not allowed by default)
	 *
	 * @param {string} sHtml
	 * @param {Object} oSanitizerRules See MakeHtml()
	 *
	 * @return {DocumentFragment} Returned as DOM, so it is not parsed a second time once sanitized
	 */
	Sanitize: function (sHtml, oSanitizerRules) {
		const aAllowedTags = Object.keys(oSanitizerRules.tags_whitelist);
		const oConfig = {
			FORBID_TAGS: oSanitizerRules.tags_blacklist,
			FORBID_ATTR: oSanitizerRules.attrs_blacklist,
			RETURN_DOM_FRAGMENT: true,
		};
		// An empty whitelist means no restriction for iTop, DOMPurify default lists apply then
		if (aAllowedTags.length > 0) {
			oConfig.ALLOWED_TAGS = aAllowedTags;
			// Attributes are allowed globally here, they are then checked for each tag by a hook (see GetSanitizer())
			oConfig.ALLOWED_ATTR = [];
			aAllowedTags.forEach((sTag) => {
				oConfig.ALLOWED_ATTR.push(...oSanitizerRules.tags_whitelist[sTag]);
			});
			oConfig.ALLOW_DATA_ATTR = false;
			oConfig.ALLOW_ARIA_ATTR = false;
		}

		// Rules are read by the hooks during the sanitization, which is synchronous
		this.oSanitizerRules = oSanitizerRules;

		return this.GetSanitizer().sanitize(sHtml, oConfig);
	},

	/**
	 * @return {Object} DOMPurify instance dedicated to the markdown viewer, so its hooks don't alter other usages in the page
	 */
	GetSanitizer: function () {
		if (this.oSanitizer === null) {
			const oSanitizer = DOMPurify(window);

			oSanitizer.addHook('uponSanitizeAttribute', (oNode, oHookEvent) => {
				const sValue = this.GetSanitizedAttributeValue(oNode.nodeName.toLowerCase(), oHookEvent.attrName, oHookEvent.attrValue);
				if (sValue === null) {
					oHookEvent.keepAttr = false;
				} else {
					oHookEvent.attrValue = sValue;
				}
			});
			oSanitizer.addHook('afterSanitizeAttributes', (oNode) => {
				// Links opened in a new window must not have access to the opener page
				if ((oNode.tagName === 'A') && oNode.hasAttribute('target')) {
					oNode.setAttribute('rel', 'noopener noreferrer');
				}
			});

			this.oSanitizer = oSanitizer;
		}

		return this.oSanitizer;
	},

	/**
	 * Check an attribute against the rules of the iTop HTML sanitizer, same as DOMSanitizer::CleanNode()
	 *
	 * @param {string} sTagName
	 * @param {string} sAttrName
	 * @param {string} sValue
	 *
	 * @return {string|null} Value to keep for the attribute, null if the attribute must be removed
	 */
	GetSanitizedAttributeValue: function (sTagName, sAttrName, sValue) {
		const oRules = this.oSanitizerRules;

		if (oRules.attrs_blacklist.indexOf(sAttrName) > -1) {
			return null;
		}
		if ((Object.keys(oRules.tags_whitelist).length > 0) && ((oRules.tags_whitelist.hasOwnProperty(sTagName) === false) || (oRules.tags_whitelist[sTagName].indexOf(sAttrName) === -1))) {
			return null;
		}
		if (oRules.attrs_whitelist.hasOwnProperty(sAttrName)) {
			const oRegExp = this.ConvertPattern(oRules.attrs_whitelist[sAttrName]);
			if ((oRegExp === null) || (oRegExp.test(sValue) === false)) {
				return null;
			}
		}
		if (sAttrName === 'style') {
			const sStyle = this.FilterStyle(sValue, oRules.styles_whitelist);

			return (sStyle !== '') ? sStyle : null;
		}

		return sValue;
	},

	/**
	 * Same as DOMSanitizer::CleanStyle()
	 *
	 * @param {string} sStyle Value of a "style" attribute
	 * @param {Array} aAllowedProperties CSS properties allowed, all of them if empty
	 *
	 * @return {string} sStyle with only the allowed CSS properties
	 */
	FilterStyle: function (sStyle, aAllowedProperties) {
		if (aAllowedProperties.length === 0) {
			return sStyle;
		}

		return sStyle.split(';')
			.filter((sDeclaration) => aAllowedProperties.indexOf(sDeclaration.split(':')[0].trim().toLowerCase()) > -1)
			.map((sDeclaration) => sDeclaration.trim())
			.join(';');
	},

	/**
	 * @param {string} sPattern PCRE pattern of the iTop HTML sanitizer, with its delimiters and modifiers (eg. "/^(http:|https:|data:)/i")
	 *
	 * @return {RegExp|null} Equivalent JS regular expression, null if it can't be converted (attributes using it are then removed)
	 */
	ConvertPattern: function (sPattern) {
		if (this.oPatternRegExps.hasOwnProperty(sPattern) === false) {
			let oRegExp = null;

			const sStartDelimiter = sPattern.charAt(0);
			const sEndDelimiter = {'(': ')', '[': ']', '{': '}', '<': '>'}[sStartDelimiter] || sStartDelimiter;
			const iEndDelimiterPos = sPattern.lastIndexOf(sEndDelimiter);
			const sModifiers = sPattern.substring(iEndDelimiterPos + 1);
			// Only modifiers with a JS equivalent are supported
			if ((iEndDelimiterPos > 0) && /^[imsu]*$/.test(sModifiers)) {
				try {
					oRegExp = new RegExp(sPattern.substring(1, iEndDelimiterPos), sModifiers);
				} catch (oException) {
					oRegExp = null;
				}
			}
			if (oRegExp === null) {
				console.warn('Molkobain markdown viewer: Could not convert the HTML sanitizer pattern "' + sPattern + '" to JS, attributes using it will be removed.');
			}

			this.oPatternRegExps[sPattern] = oRegExp;
		}

		return this.oPatternRegExps[sPattern];
	},

	/**
	 * @param {Node} oParentNode
	 *
	 * @return {Array} Markdown blocks (paragraphs, lists, ...) of the oParentNode children
	 */
	ConvertChildrenToBlocks: function (oParentNode) {
		const aBlocks = [];
		let sInlineText = '';
		const fFlushInlineText = () => {
			const sBlock = this.CleanInlineText(sInlineText);
			if (sBlock !== '') {
				aBlocks.push(sBlock);
			}
			sInlineText = '';
		};

		oParentNode.childNodes.forEach((oNode) => {
			if (this.IsBlockNode(oNode)) {
				fFlushInlineText();
				aBlocks.push(...this.ConvertBlockNode(oNode));
			} else {
				sInlineText += this.ConvertInlineNode(oNode);
			}
		});
		fFlushInlineText();

		return aBlocks;
	},

	/**
	 * @param {Element} oNode Block node
	 *
	 * @return {Array} Markdown blocks of oNode
	 */
	ConvertBlockNode: function (oNode) {
		const sTagName = oNode.tagName.toLowerCase();
		switch (sTagName) {
			case 'h1':
			case 'h2':
			case 'h3':
			case 'h4':
			case 'h5':
			case 'h6':
				return this.ConvertHeading(oNode, parseInt(sTagName.charAt(1), 10));

			case 'ul':
			case 'ol':
				return this.ConvertList(oNode);

			case 'blockquote':
				return this.ConvertBlockquote(oNode);

			case 'pre':
				return this.ConvertPreformattedText(oNode);

			case 'table':
				return this.ConvertTable(oNode);

			case 'hr':
				return ['---'];

			case 'p': {
				const aBlocks = this.ConvertChildrenToBlocks(oNode);

				// An empty paragraph is a blank line typed by the user
				return (aBlocks.length > 0) ? aBlocks : [''];
			}

			default:
				return this.ConvertChildrenToBlocks(oNode);
		}
	},

	/**
	 * @param {Node} oNode Inline node
	 *
	 * @return {string} Markdown of oNode
	 */
	ConvertInlineNode: function (oNode) {
		if (oNode.nodeType === Node.TEXT_NODE) {
			// Collapse whitespaces as the browser does, non-breaking spaces are kept
			return oNode.nodeValue.replace(/[ \t\n\r\f]+/g, ' ');
		}
		if (oNode.nodeType !== Node.ELEMENT_NODE) {
			return '';
		}

		const sTagName = oNode.tagName.toLowerCase();
		if (this.IGNORED_TAGS.indexOf(sTagName) > -1) {
			return '';
		}
		// Block within an inline element (invalid markup), put it on its own lines
		if (this.IsBlockNode(oNode)) {
			return '\n' + this.JoinBlocks(this.ConvertBlockNode(oNode)) + '\n';
		}

		switch (sTagName) {
			case 'br':
				return '\n';

			case 'img':
				return this.ConvertImage(oNode);

			case 'a':
				return this.ConvertLink(oNode);

			case 'strong':
			case 'b':
				return this.WrapInlineText(this.ConvertInlineChildren(oNode), '**');

			case 'em':
			case 'i':
				return this.WrapInlineText(this.ConvertInlineChildren(oNode), '*');

			case 'code':
				return this.ConvertInlineCode(oNode);

			default:
				// Other formatting (underline, colors, ...) has no markdown equivalent, only its text is kept
				return this.ConvertInlineChildren(oNode);
		}
	},

	/**
	 * @param {Node} oNode
	 *
	 * @return {string} Markdown of the oNode children, considered as inline nodes
	 */
	ConvertInlineChildren: function (oNode) {
		let sText = '';
		oNode.childNodes.forEach((oChildNode) => {
			sText += this.ConvertInlineNode(oChildNode);
		});

		return sText;
	},

	/**
	 * @param {Element} oNode
	 * @param {number} iLevel 1 to 6
	 *
	 * @return {Array}
	 */
	ConvertHeading: function (oNode, iLevel) {
		const sText = this.CleanInlineText(this.ConvertInlineChildren(oNode)).replace(/\n+/g, ' ');
		if (sText.trim() === '') {
			return [];
		}

		// Heading applied through the toolbar on a line already typed with the markdown syntax
		if (sText.charAt(0) === '#') {
			return [sText];
		}

		return ['#'.repeat(iLevel) + ' ' + sText];
	},

	/**
	 * @param {Element} oNode "ul" or "ol" element
	 *
	 * @return {Array}
	 */
	ConvertList: function (oNode) {
		const bOrdered = (oNode.tagName.toLowerCase() === 'ol');
		let iItemNumber = parseInt(oNode.getAttribute('start'), 10);
		if (isNaN(iItemNumber)) {
			iItemNumber = 1;
		}

		const aItems = [];
		oNode.childNodes.forEach((oChildNode) => {
			if (oChildNode.nodeType !== Node.ELEMENT_NODE) {
				return;
			}

			const sChildTagName = oChildNode.tagName.toLowerCase();
			// List directly nested in a list (invalid markup produced by some editors), attach it to the previous item
			if (((sChildTagName === 'ul') || (sChildTagName === 'ol')) && (aItems.length > 0)) {
				aItems[aItems.length - 1] += '\n    ' + this.ConvertList(oChildNode).join('\n').replace(/\n/g, '\n    ');
				return;
			}

			// Item lines after the first one are indented so they stay in the item
			const sMarker = bOrdered ? (iItemNumber++) + '. ' : '* ';
			aItems.push(sMarker + this.ConvertChildrenToBlocks(oChildNode).join('\n').replace(/\n/g, '\n    '));
		});

		return (aItems.length > 0) ? [aItems.join('\n')] : [];
	},

	/**
	 * @param {Element} oNode
	 *
	 * @return {Array}
	 */
	ConvertBlockquote: function (oNode) {
		const sContent = this.JoinBlocks(this.ConvertChildrenToBlocks(oNode));
		if (sContent.trim() === '') {
			return [];
		}

		return [sContent.split('\n').map((sLine) => (sLine === '') ? '>' : '> ' + sLine).join('\n')];
	},

	/**
	 * @param {Element} oNode "pre" element (eg. CKEditor code block)
	 *
	 * @return {Array}
	 */
	ConvertPreformattedText: function (oNode) {
		const sCode = this.ReplaceNonBreakingSpaces(this.GetPreformattedText(oNode)).replace(/^\n+|\n+$/g, '');
		if (sCode.trim() === '') {
			return [];
		}

		// Language of a CKEditor code block (eg. "language-php"), except its default one
		let sLanguage = '';
		const oCodeNode = oNode.querySelector('code[class*="language-"]');
		if (oCodeNode !== null) {
			const aMatches = oCodeNode.className.match(/language-([\w#+-]+)/);
			if ((aMatches !== null) && (aMatches[1] !== 'plaintext')) {
				sLanguage = aMatches[1];
			}
		}

		// Fence must be longer than any sequence of backticks in the code
		let iFenceLength = 3;
		(sCode.match(/`+/g) || []).forEach((sBackticks) => {
			iFenceLength = Math.max(iFenceLength, sBackticks.length + 1);
		});
		const sFence = '`'.repeat(iFenceLength);

		return [sFence + sLanguage + '\n' + sCode + '\n' + sFence];
	},

	/**
	 * @param {Node} oNode
	 *
	 * @return {string} Text of oNode with its spaces and line breaks kept
	 */
	GetPreformattedText: function (oNode) {
		let sText = '';
		oNode.childNodes.forEach((oChildNode) => {
			if (oChildNode.nodeType === Node.TEXT_NODE) {
				sText += oChildNode.nodeValue;
			} else if (oChildNode.nodeType === Node.ELEMENT_NODE) {
				sText += (oChildNode.tagName.toLowerCase() === 'br') ? '\n' : this.GetPreformattedText(oChildNode);
			}
		});

		return sText;
	},

	/**
	 * @param {Element} oNode "table" element
	 *
	 * @return {Array}
	 */
	ConvertTable: function (oNode) {
		const aRows = [];
		let iColumnsCount = 0;
		Array.prototype.forEach.call(oNode.rows, (oRowNode) => {
			const aCells = [];
			Array.prototype.forEach.call(oRowNode.cells, (oCellNode) => {
				// Cell must fit on one line, and its pipes must not be taken as cells separators
				aCells.push(this.ConvertChildrenToBlocks(oCellNode).join(' ').replace(/\n/g, ' ').replace(/\|/g, '&#124;'));
			});
			aRows.push(aCells);
			iColumnsCount = Math.max(iColumnsCount, aCells.length);
		});
		if (iColumnsCount === 0) {
			return [];
		}

		const fMakeLine = (aCells) => {
			const aLineCells = aCells.slice();
			while (aLineCells.length < iColumnsCount) {
				aLineCells.push('');
			}

			return '| ' + aLineCells.join(' | ') + ' |';
		};
		// Markdown tables always have a header, the first row is used for it
		const aLines = [fMakeLine(aRows[0]), fMakeLine(new Array(iColumnsCount).fill('---'))];
		aRows.slice(1).forEach((aCells) => {
			aLines.push(fMakeLine(aCells));
		});

		return [aLines.join('\n')];
	},

	/**
	 * @param {Element} oNode "img" element
	 *
	 * @return {string}
	 */
	ConvertImage: function (oNode) {
		const sSrc = oNode.getAttribute('src') || '';
		if (sSrc === '') {
			return '';
		}

		return '![' + (oNode.getAttribute('alt') || '').replace(/[\[\]]/g, '') + '](' + this.EscapeUrl(sSrc) + ')';
	},

	/**
	 * @param {Element} oNode "a" element
	 *
	 * @return {string}
	 */
	ConvertLink: function (oNode) {
		const sText = this.ConvertInlineChildren(oNode);
		const sTrimmedText = sText.trim();
		const sHref = oNode.getAttribute('href') || '';

		// Link without destination, or created by CKEditor from a typed URL (possibly in a typed markdown link): Keep the text as typed
		if ((sHref === '') || (sTrimmedText === '') || (sTrimmedText === sHref) || ('mailto:' + sTrimmedText === sHref)) {
			return sText;
		}

		return '[' + sText + '](' + this.EscapeUrl(sHref) + ')';
	},

	/**
	 * @param {Element} oNode "code" element outside a "pre" element
	 *
	 * @return {string}
	 */
	ConvertInlineCode: function (oNode) {
		const sCode = oNode.textContent.replace(/[ \t\n\r\f]+/g, ' ');
		if (sCode.trim() === '') {
			return sCode;
		}

		return (sCode.indexOf('`') > -1) ? '`` ' + sCode + ' ``' : '`' + sCode + '`';
	},

	/**
	 * @param {string} sText
	 * @param {string} sMarker Markdown emphasis marker (eg. "**" for bold)
	 *
	 * @return {string} sText wrapped in sMarker, leading / trailing spaces are kept outside, otherwise the emphasis would not be valid
	 */
	WrapInlineText: function (sText, sMarker) {
		const aMatches = sText.match(/^(\s*)([\s\S]*?)(\s*)$/);
		if (aMatches[2] === '') {
			return sText;
		}

		return aMatches[1] + sMarker + aMatches[2] + sMarker + aMatches[3];
	},

	/**
	 * @param {string} sUrl
	 *
	 * @return {string} sUrl usable as the destination of a markdown link / image
	 */
	EscapeUrl: function (sUrl) {
		return sUrl.replace(/ /g, '%20').replace(/\(/g, '%28').replace(/\)/g, '%29');
	},

	/**
	 * @param {string} sText Text of inline nodes, with whitespaces collapsed
	 *
	 * @return {string} sText without the spaces coming from the HTML source code, while the ones typed by the user (non-breaking spaces) are kept
	 */
	CleanInlineText: function (sText) {
		const sCleanedText = sText.replace(/ {2,}/g, ' ').replace(/^ +| +$/gm, '');

		return this.ReplaceNonBreakingSpaces(sCleanedText).replace(/^\n+|\n+$/g, '');
	},

	/**
	 * @param {string} sText
	 *
	 * @return {string} sText with its non-breaking spaces replaced with regular spaces, otherwise markdown would not consider them as spaces (eg. for a list item indentation)
	 */
	ReplaceNonBreakingSpaces: function (sText) {
		return sText.replace(/ /g, ' ');
	},

	/**
	 * @param {Node} oNode
	 *
	 * @return {boolean}
	 */
	IsBlockNode: function (oNode) {
		return (oNode.nodeType === Node.ELEMENT_NODE) && (this.BLOCK_TAGS.indexOf(oNode.tagName.toLowerCase()) > -1);
	},

	/**
	 * @param {Array} aBlocks Markdown blocks
	 *
	 * @return {string} aBlocks separated by a blank line, unless they are consecutive lines of the same construct (see IsLineContinuation())
	 */
	JoinBlocks: function (aBlocks) {
		let sMarkdown = '';
		let bInCodeFence = false;
		aBlocks.forEach((sBlock, iIndex) => {
			if (iIndex > 0) {
				sMarkdown += this.IsLineContinuation(aBlocks[iIndex - 1], sBlock, bInCodeFence) ? '\n' : '\n\n';
			}
			sMarkdown += sBlock;

			sBlock.split('\n').forEach((sLine) => {
				if (/^\s{0,3}(```|~~~)/.test(sLine)) {
					bInCodeFence = !bInCodeFence;
				}
			});
		});

		return sMarkdown;
	},

	/**
	 * Each line typed with "Enter" in CKEditor is a paragraph. When consecutive one-line paragraphs belong to a construct requiring consecutive lines (code block, table, list), they must not be separated by a blank line.
	 * Note: Multi-line blocks are left untouched, as they come from lines typed with "Shift + Enter" or from a pasted text, where blank lines are intended.
	 *
	 * @param {string} sPreviousBlock
	 * @param {string} sBlock
	 * @param {boolean} bInCodeFence Whether sPreviousBlock ends inside a fenced code block
	 *
	 * @return {boolean}
	 */
	IsLineContinuation: function (sPreviousBlock, sBlock, bInCodeFence) {
		if ((sPreviousBlock.indexOf('\n') > -1) || (sBlock.indexOf('\n') > -1)) {
			return false;
		}
		if (bInCodeFence) {
			return true;
		}

		const oTableRowRegExp = /^\s*\||\|\s*$/;
		const oListItemRegExp = /^\s*([*+-]|\d+[.)])\s/;

		return (oTableRowRegExp.test(sPreviousBlock) && oTableRowRegExp.test(sBlock))
			|| (oListItemRegExp.test(sPreviousBlock) && oListItemRegExp.test(sBlock));
	},
};
